package com.valor.workflow;

import com.valor.auth.*;
import com.valor.realtime.RealtimeEventService;
import org.springframework.context.ApplicationEventPublisher;
import java.time.LocalDateTime;
import java.util.*;
import org.springframework.data.domain.*;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import static com.valor.workflow.ReassignmentDtos.*;

@Service @Transactional
public class ReassignmentService {
    private final ReassignmentRepository requests; private final RequestRepository jobs; private final AssignmentRepository assignments;
    private final WorkflowIdentityAccess identities; private final AssetIdentityAccess access; private final AuditService audit; private final RealtimeEventService realtime; private final ApplicationEventPublisher events;
    public ReassignmentService(ReassignmentRepository requests, RequestRepository jobs, AssignmentRepository assignments, WorkflowIdentityAccess identities, AssetIdentityAccess access, AuditService audit, RealtimeEventService realtime, ApplicationEventPublisher events) {
        this.requests=requests; this.jobs=jobs; this.assignments=assignments; this.identities=identities; this.access=access; this.audit=audit; this.realtime=realtime; this.events=events;
    }
    public View create(Long jobId, Create input) {
        User actor=access.actor(); TechnicianProfile tech=identities.technician(actor); ServiceRequest job=jobs.lockById(jobId).orElseThrow(ReassignmentService::missing); nonterminal(job);
        TechnicianAssignment active=owned(job, tech); if(requests.findByServiceRequestIdAndStatus(jobId, ReassignmentStatus.PENDING).isPresent()) throw conflict("A reassignment request is already pending.");
        if(job.getStatus().ordinal() >= RequestStatus.REACHED_SITE.ordinal() && !hasHandover(input.handover())) throw new WorkflowException(400,"Handover information is required after work has started.");
        TechnicianReassignmentRequest row=new TechnicianReassignmentRequest(); row.setServiceRequest(job); row.setRequestingTechnician(tech); row.setOriginalAssignment(active); row.setReasonCode(input.reasonCode()); row.setReasonExplanation(clean(input.reasonExplanation())); apply(row,input.handover()); requests.saveAndFlush(row);
        audit.record("TECHNICIAN_REASSIGNMENT_REQUEST", "TECHNICIAN_REASSIGNMENT_REQUEST", row.getId(), "Technician requested reassignment for service request="+jobId);
        realtime.publish("TECHNICIAN_REASSIGNMENT_REQUESTED","SERVICE_REQUEST",jobId,ReassignmentStatus.PENDING.name(),Set.of(actor.getId())); return view(row);
    }
    @Transactional(readOnly=true) public PageView<View> technicianList(Long jobId,int page,int size){ TechnicianProfile t=identities.technician(access.actor()); Page<TechnicianReassignmentRequest> p=requests.findByServiceRequestIdAndRequestingTechnicianId(jobId,t.getId(),paging(page,size)); return technicianPage(p); }
    @Transactional(readOnly=true) public PageView<View> adminList(ReassignmentStatus status,int page,int size){ admin(access.actor()); Page<TechnicianReassignmentRequest> p=status==null?requests.findAll(paging(page,size)):requests.findByStatus(status,paging(page,size)); return page(p); }
    @Transactional(readOnly=true) public View adminRead(Long id){ admin(access.actor()); return view(requests.findById(id).orElseThrow(ReassignmentService::missing)); }
    public View reject(Long id, Decision input){ User actor=access.actor(); admin(actor); TechnicianReassignmentRequest row=locked(id); pending(row); row.setStatus(ReassignmentStatus.REJECTED); row.setReviewedBy(actor); row.setDecisionReason(clean(input.reason())); row.setDecidedAt(LocalDateTime.now()); audit.record("TECHNICIAN_REASSIGNMENT_REJECT","TECHNICIAN_REASSIGNMENT_REQUEST",id,"Rejected reassignment request",null,"status=REJECTED","SUCCESS"); return view(row); }
    public View cancel(Long id, Decision input){ User actor=access.actor(); admin(actor); TechnicianReassignmentRequest row=locked(id); pending(row); row.setStatus(ReassignmentStatus.CANCELLED); row.setReviewedBy(actor); row.setDecisionReason(clean(input.reason())); row.setCancelledAt(LocalDateTime.now()); return view(row); }
    public View withdraw(Long id){ User actor=access.actor(); TechnicianProfile t=identities.technician(actor); TechnicianReassignmentRequest row=locked(id); pending(row); if(!row.getRequestingTechnician().getId().equals(t.getId())) throw denied(); row.setStatus(ReassignmentStatus.WITHDRAWN); row.setWithdrawnAt(LocalDateTime.now()); return view(row); }
    public View approve(Long id, Approve input){ User actor=access.actor(); admin(actor); TechnicianReassignmentRequest requested=requests.findById(id).orElseThrow(ReassignmentService::missing); ServiceRequest job=jobs.lockById(requested.getServiceRequest().getId()).orElseThrow(ReassignmentService::missing); TechnicianReassignmentRequest row=locked(id); pending(row); nonterminal(job); TechnicianAssignment old=assignments.active(job.getId()).orElseThrow(()->conflict("The original assignment is no longer active.")); if(!old.getId().equals(row.getOriginalAssignment().getId())||!old.getTechnician().getId().equals(row.getRequestingTechnician().getId())) throw conflict("The original assignment has changed."); TechnicianProfile replacement=identities.activeTechnician(input.replacementTechnicianProfileId()); if(replacement.getId().equals(old.getTechnician().getId())) throw new WorkflowException(400,"Replacement must differ from the current technician.");
        old.setStatus(AssignmentStatus.RELEASED); old.setReleasedAt(LocalDateTime.now()); assignments.flush(); TechnicianAssignment next=new TechnicianAssignment(); next.setRequest(job); next.setTechnician(replacement); next.setAssignedBy(actor); next.setNotes("Reassignment request #"+row.getId()+": "+(input.decisionReason()==null?"":clean(input.decisionReason()))); assignments.saveAndFlush(next);
        row.setStatus(ReassignmentStatus.TRANSFERRED); row.setReviewedBy(actor); row.setDecisionReason(input.decisionReason()==null?null:clean(input.decisionReason())); row.setReplacementTechnician(replacement); row.setNewAssignment(next); row.setDecidedAt(LocalDateTime.now()); row.setTransferredAt(LocalDateTime.now()); audit.record("TECHNICIAN_REASSIGNMENT_TRANSFER","TECHNICIAN_REASSIGNMENT_REQUEST",id,"Transferred service request="+job.getId(),"assignment="+old.getId(),"assignment="+next.getId(),"SUCCESS"); events.publishEvent(new ReassignmentNotificationEvent(id,job.getId(),replacement.getUser().getId(),old.getTechnician().getUser().getId())); Set<Long> recipients=new HashSet<>(Set.of(replacement.getUser().getId(),old.getTechnician().getUser().getId(),job.getCustomer().getUser().getId())); realtime.publish("JOB_ASSIGNMENT_CHANGED","SERVICE_REQUEST",job.getId(),job.getStatus().name(),recipients); return view(row);
    }
    @Transactional(readOnly=true) public List<AssignmentHistory> history(Long jobId){ admin(access.actor()); return assignments.findByRequestIdOrderByAssignedAtAscIdAsc(jobId).stream().map(a->new AssignmentHistory(a.getId(),jobId,a.getTechnician().getId(),a.getStatus(),a.getAssignedBy().getId(),a.getAssignedAt(),a.getAcceptedAt(),a.getReleasedAt(),a.getNotes())).toList(); }
    private TechnicianReassignmentRequest locked(Long id){return requests.lockById(id).orElseThrow(ReassignmentService::missing);} private void pending(TechnicianReassignmentRequest r){if(r.getStatus()!=ReassignmentStatus.PENDING)throw conflict("Reassignment request is no longer pending.");}
    private TechnicianAssignment owned(ServiceRequest j,TechnicianProfile t){TechnicianAssignment a=assignments.active(j.getId()).orElseThrow(()->denied());if(!a.getTechnician().getId().equals(t.getId()))throw denied();return a;}
    private void nonterminal(ServiceRequest j){if(j.getStatus()==RequestStatus.COMPLETED||j.getStatus()==RequestStatus.CANCELLED)throw conflict("Request is terminal.");}
    private static boolean hasHandover(Handover h){return h!=null&&StreamUtil.any(h.workCompleted(),h.workPending(),h.partsSafetyContext(),h.otherContext());}
    private static void apply(TechnicianReassignmentRequest r,Handover h){if(h!=null){r.setWorkCompleted(clean(h.workCompleted()));r.setWorkPending(clean(h.workPending()));r.setPartsSafetyContext(clean(h.partsSafetyContext()));r.setOtherHandoverContext(clean(h.otherContext()));}}
    private PageView<View> page(Page<TechnicianReassignmentRequest> p){return new PageView<>(p.getContent().stream().map(this::view).toList(),p.getNumber(),p.getSize(),p.getTotalElements(),p.getTotalPages());}
    private PageView<View> technicianPage(Page<TechnicianReassignmentRequest> p){return new PageView<>(p.getContent().stream().map(this::technicianView).toList(),p.getNumber(),p.getSize(),p.getTotalElements(),p.getTotalPages());}
    private View technicianView(TechnicianReassignmentRequest r){return new View(r.getId(),r.getServiceRequest().getId(),r.getOriginalAssignment().getId(),r.getRequestingTechnician().getId(),r.getReasonCode(),r.getReasonExplanation(),null,null,null,null,r.getStatus(),null,null,null,null,r.getCreatedAt(),r.getDecidedAt(),r.getTransferredAt(),r.getWithdrawnAt(),r.getCancelledAt());}
    private View view(TechnicianReassignmentRequest r){return new View(r.getId(),r.getServiceRequest().getId(),r.getOriginalAssignment().getId(),r.getRequestingTechnician().getId(),r.getReasonCode(),r.getReasonExplanation(),r.getWorkCompleted(),r.getWorkPending(),r.getPartsSafetyContext(),r.getOtherHandoverContext(),r.getStatus(),r.getReviewedBy()==null?null:r.getReviewedBy().getId(),r.getDecisionReason(),r.getReplacementTechnician()==null?null:r.getReplacementTechnician().getId(),r.getNewAssignment()==null?null:r.getNewAssignment().getId(),r.getCreatedAt(),r.getDecidedAt(),r.getTransferredAt(),r.getWithdrawnAt(),r.getCancelledAt());}
    private Pageable paging(int p,int s){if(p<0||s<1||s>100)throw new WorkflowException(400,"Please choose a valid page number.");return PageRequest.of(p,s,Sort.by(Sort.Direction.DESC,"createdAt","id"));} private static String clean(String v){return v==null?null:v.trim();} private static void admin(User u){if(u.getRole()!=Role.ADMIN&&u.getRole()!=Role.SUPER_ADMIN)throw denied();} private static AccessDeniedException denied(){return new AccessDeniedException("You do not have permission to access this information.");} private static WorkflowException missing(){return new WorkflowException(404,"Reassignment request or service request not found");} private static WorkflowException conflict(String m){return new WorkflowException(409,m);}
    static final class StreamUtil { static boolean any(String... v){for(String x:v)if(x!=null&&!x.isBlank())return true;return false;} }
}
